#include "Managers/HorizonSharedObjectsManager.h"
void UHorizonSharedObjectsManager::RequestCollections(const FString& UserId,const FString& AfterKey,int32 Limit,int64 CatalogRevision){const auto D=FOnSharedCollectionsComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonSharedCollectionPage& R,const FString& Code,const FString& Message){OnCollectionsResult.Broadcast(Ok,R,Code,Message);});GetCollections(UserId,D,AfterKey,Limit,CatalogRevision);}
void UHorizonSharedObjectsManager::RequestUsage(const FString& UserId,const FString& Collection){const auto D=FOnSharedUsageComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonSharedUsage& R,const FString& Code,const FString& Message){OnUsageResult.Broadcast(Ok,R,Code,Message);});GetUsage(UserId,Collection,D);}
void UHorizonSharedObjectsManager::RequestObject(const FString& UserId,const FString& Collection,const FString& ObjectId){const auto D=FOnSharedObjectComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonSharedObjectRead& R,const FString& Code,const FString& Message){OnObjectResult.Broadcast(Ok,R,Code,Message);});GetObject(UserId,Collection,ObjectId,D);}
void UHorizonSharedObjectsManager::RequestQuery(const FString& UserId,const FString& Collection,const FHorizonSharedQuery& Query){const auto D=FOnSharedQueryComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonSharedQueryResult& R,const FString& Code,const FString& Message){OnQueryResult.Broadcast(Ok,R,Code,Message);});QueryObjects(UserId,Collection,Query,D);}
void UHorizonSharedObjectsManager::CreateSharedObject(const FString& UserId,const FString& Collection,int64 ExpectedUsageRevision,const FHorizonSharedObjectInput& Input,const FString& GroupId){const auto D=FOnSharedWriteComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonSharedWriteResult& R,const FString& Code,const FString& Message){OnWriteResult.Broadcast(Ok,R,Code,Message);});CreateObject(UserId,Collection,ExpectedUsageRevision,Input,D,GroupId);}
void UHorizonSharedObjectsManager::UpdateSharedObject(const FString& UserId,const FString& Collection,const FString& ObjectId,int64 ExpectedObjectRevision,const FHorizonSharedObjectInput& Input){const auto D=FOnSharedWriteComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonSharedWriteResult& R,const FString& Code,const FString& Message){OnWriteResult.Broadcast(Ok,R,Code,Message);});UpdateObject(UserId,Collection,ObjectId,ExpectedObjectRevision,Input,D);}
void UHorizonSharedObjectsManager::DeleteSharedObject(const FString& UserId,const FString& Collection,const FString& ObjectId,int64 ExpectedObjectRevision){const auto D=FOnSharedDeleteComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonSharedDeleteResult& R,const FString& Code,const FString& Message){OnDeleteResult.Broadcast(Ok,R,Code,Message);});DeleteObject(UserId,Collection,ObjectId,ExpectedObjectRevision,D);}
